const summary2 = flow('LR', [['n', 'Negatives: odd or pi minus'], ['c', 'Complementary pairs add to pi by 2'], ['s', 'Sum formulae with conditions'], ['d', 'Double and triple forms'], ['e', 'Equations: always check roots']], [['n', 'c'], ['c', 's'], ['s', 'd'], ['d', 'e']], 'Summary flow of Part 2: negative arguments make the function odd or give pi minus; complementary pairs add to pi by 2; sum formulae need their conditions; double and triple forms; and equations need every root checked.', 'Part 2 in one line.');
const tips2 = table(['Question type', 'How marks are given'], [['Prove an identity (3)', 'angles named 1, formula with condition 1, simplification 1'], ['Equation (3–5)', 'combine 1, algebra 1–2, roots tested 1, rejection 1'], ['Double / triple form (2–3)', 'condition checked, substitution, answer'], ['Value of a trigonometric function of an inverse (1–2)', 'triangle or identity, correct sign']], 'Exam tips table for Part 2: an identity proof gives marks for naming the angles, using the formula with its condition and simplifying; an equation gives marks for combining, the algebra, testing and rejecting roots; double and triple forms need the condition checked; values of a trigonometric function of an inverse need the correct sign.', 'A condition that is never checked costs a mark.');

// ================================================================ deck 1
const d1 = deck({
  part: 1,
  title: 'Inverse Trigonometric Functions — Part 1: Principal values and graphs',
  goals: ['Explain why a trigonometric function must be restricted before it can be inverted', 'State the domain and principal-value range of all six inverse trigonometric functions', 'Find principal values, including expressions such as the inverse sine of the sine of an angle', 'Find the domain of a function built from an inverse trigonometric function', 'Sketch the graphs of the inverse sine, cosine and tangent as reflections in y = x'],
  slides: [
    sl('title', 'Inverse Trigonometric Functions, Part 1', { b: 'Given a ratio, which angle? A calculator always answers with one particular angle.', v: route1, n: 'A ramp rises one metre for every two metres along the ground. What is its angle? To answer, we must run the tangent function backwards. In this part you will learn how mathematicians choose one answer out of infinitely many, meet all six inverse trigonometric functions, and draw their graphs.' }),
    sl('concept', 'Why restrict first?', { b: r`$\sin x$ is many-one on $\mathbb{R}$, so it has no inverse. On $\left[-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right]$ it is one-one and onto $[-1, 1]$.`, v: pSinRestrict, n: 'The sine wave takes every value between minus one and one infinitely often, so it cannot be undone as it stands. Keep only the piece from minus pi by two to pi by two. On that piece the curve rises once and meets each value exactly once, so it has an inverse. That piece is called the principal-value branch.' }),
    sl('concept', 'The six principal-value branches', { b: 'Each inverse function returns angles only from its principal range.', v: branchTable, n: 'Here are all six inverse functions. The inverse sine and inverse cosine accept numbers from minus one to one. The inverse tangent and inverse cotangent accept every real number. The inverse secant and inverse cosecant accept numbers outside the open interval from minus one to one. Notice that the cosine family uses ranges starting at zero.' }),
    sl('diagram', 'The graph of the inverse sine', { b: r`$y = \sin^{-1} x$ rises from $\left(-1, -\dfrac{\pi}{2}\right)$ to $\left(1, \dfrac{\pi}{2}\right)$.`, v: pAsin, n: 'The inverse sine curve starts at minus one with height minus pi by two, passes through the origin and ends at one with height pi by two. It is increasing and it is odd: turning the input negative turns the output negative. The curve is steepest at its two ends.' }),
    sl('example', 'Worked example 1: five principal values', { b: 'Find each value using the correct branch.', ul: [r`$\sin^{-1}\left(-\frac12\right) = -\frac{\pi}{6}$ (in $\left[-\frac{\pi}{2}, \frac{\pi}{2}\right]$)`, r`$\cot^{-1}\left(-\frac{1}{\sqrt3}\right) = \frac{2\pi}{3}$ (in $(0, \pi)$, not $-\frac{\pi}{3}$)`, r`$\sec^{-1}\sqrt2 = \frac{\pi}{4}$ (from $\cos\theta = \frac{1}{\sqrt2}$)`], v: we1Table, n: 'For each value, first recall the branch, then find the one angle in it with the given ratio. The inverse sine of minus one half is minus pi by six. The inverse cotangent of a negative number must lie between pi by two and pi, so it is two pi by three. For the inverse secant, turn the secant into a cosine first.' }),
    sl('check', 'Quick check: the inverse cotangent', { b: 'Choose the principal value of the inverse cotangent of a negative number.', chk: 'm04', n: 'Remember that the inverse cotangent never gives a negative angle. Its answers lie strictly between zero and pi.' }),
    sl('diagram', 'The graph of the inverse cosine', { b: r`$y = \cos^{-1} x$ falls from $(-1, \pi)$ to $(1, 0)$.`, v: pAcos, n: 'The inverse cosine curve begins at the point minus one, pi, passes through zero, pi by two, and ends on the x axis at one. It is decreasing everywhere. Because its range is from zero to pi, it never gives a negative answer, which is why the inverse cosine of a negative number is an obtuse angle.' }),
    sl('diagram', 'Inverse tangent and inverse cotangent', { b: r`Both are defined on all of $\mathbb{R}$; $\tan^{-1} x$ rises between $-\dfrac{\pi}{2}$ and $\dfrac{\pi}{2}$, $\cot^{-1} x$ falls between $\pi$ and $0$.`, v: pAtanCot, n: 'The inverse tangent accepts every real number and rises between two horizontal asymptotes at minus pi by two and pi by two. The inverse cotangent falls from pi towards zero. The two curves cross at the point one, pi by four, and at every input their heights add up to pi by two.' }),
    sl('example', 'Worked example 2: a domain from the argument', { b: r`Find the domain of $f(x) = \cos^{-1}\dfrac{2x - 1}{5}$.`, ul: ['The argument of the inverse cosine must lie in $[-1, 1]$', 'Solve the double inequality', 'Domain $[-2, 3]$'], v: we2Table, n: 'An inverse cosine only accepts numbers from minus one to one, so put the whole argument between minus one and one. Multiply through by five, add one and divide by two. The domain is the closed interval from minus two to three. Check an end point: at three the argument is exactly one.' }),
    sl('check', 'Quick check: undoing a cosine', { b: 'An even function and a principal branch: which angle comes back?', chk: 'm09', n: 'Cosine does not change when the angle changes sign. Then ask whether the angle lies between zero and pi.' }),
    sl('diagram', 'The inverse secant in two pieces', { b: r`$\sec^{-1} x$: domain $\mathbb{R} - (-1, 1)$, range $[0, \pi] - \left\{\dfrac{\pi}{2}\right\}$.`, v: pAsec, n: 'The inverse secant has two separate pieces, because the secant never takes values strictly between minus one and one. Both pieces rise. The height pi by two is never reached, since the secant of a right angle is undefined. To evaluate it, rewrite the secant as one over a cosine.' }),
    sl('concept', 'Inverse of a trigonometric value', { b: r`$\sin^{-1}(\sin\theta) = \theta$ only when $\theta \in \left[-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right]$; otherwise find the angle in the branch with the same sine.`, v: invOfSin, n: 'Be careful with expressions like the inverse sine of the sine of an angle. They do not simply cancel. The answer must lie in the principal branch, so the inverse sine of the sine of seven pi by six is minus pi by six, not seven pi by six. The table shows four cases.' }),
    sl('example', 'Worked example 3: inverse cosine of a cosine', { b: r`Find $\cos^{-1}\left(\cos\dfrac{5\pi}{3}\right)$.`, ul: [r`$\frac{5\pi}{3}$ is outside $[0, \pi]$`, r`$\cos\frac{5\pi}{3} = \cos\left(2\pi - \frac{5\pi}{3}\right) = \cos\frac{\pi}{3}$`, r`Answer $\frac{\pi}{3}$`], v: we3Table, n: 'The angle five pi by three is outside the cosine branch. Use the fact that cosine is unchanged when an angle is replaced by two pi minus the angle. That gives pi by three, which lies between zero and pi. So the inverse cosine of the cosine of five pi by three is pi by three.' }),
    sl('check', 'Quick check: a decreasing inverse', { b: 'Which inverse function falls on its whole domain?', chk: 'm12', n: 'Picture each graph from left to right. Only one of them goes downhill all the way.' }),
    sl('diagram', 'Graphs as reflections', { b: r`Reflect each principal branch in $y = x$ to get the inverse graph.`, v: pMirror, n: 'Every inverse graph is the reflection of its branch in the line y equals x. The point pi by two, one on the sine branch becomes the point one, pi by two on the inverse sine curve. Use this to sketch any of the inverse graphs quickly in the examination.' }),
    sl('check', 'Quick check: true or false?', { b: 'Can an inverse sine ever equal two?', chk: 'tf4', n: 'Compare two with the largest value the inverse sine can take, which is pi by two.' }),
    sl('summary', 'Summary', { ul: ['Restrict to a one-one branch, then invert', 'Learn the six domains and principal ranges', r`$\sin^{-1}(\sin\theta) = \theta$ only inside the branch`, 'Graphs: reflect the branch in $y = x$'], v: summary1, n: 'To sum up this part. Each trigonometric function is first restricted to a branch where it is one-one. The inverse then returns angles only from that branch. Learn the table of domains and ranges, take care with the inverse of a trigonometric value, and draw each graph as a reflection in y equals x.' }),
    sl('exam-tips', 'Exam tips', { ul: ['Write the branch before the value', 'Negative inputs: the cosine family gives obtuse angles', 'For a domain, solve the double inequality', 'In graphs, mark end points and asymptotes'], v: tips1, n: 'In the examination, always say which branch you are using before you give a value. Remember that the inverse cosine, cotangent and secant of a negative number give obtuse angles. For a domain, solve a double inequality. In a graph, mark the end points and any asymptotes.' }),
  ],
});

// ================================================================ deck 2
const d2 = deck({
  part: 2,
  title: 'Inverse Trigonometric Functions — Part 2: Properties, formulae and equations',
  goals: ['Use the rules for negative arguments and the complementary identities', 'Convert an inverse trigonometric expression from one function to another', 'Apply the sum and difference formulae for inverse tangent, sine and cosine with their conditions', 'Use the double and triple forms of the inverse tangent and inverse sine', 'Solve equations involving inverse trigonometric functions and test every root'],
  slides: [
    sl('title', 'Inverse Trigonometric Functions, Part 2', { b: 'Identities, formulae and equations: always with their conditions.', v: route2, n: 'In this part we work with inverse trigonometric functions algebraically. We start with simple properties, then combine two inverse tangents into one, use double and triple forms, and finally solve equations. Throughout, every formula comes with a condition, and checking that condition is where marks are won or lost.' }),
    sl('concept', 'Negative arguments', { b: r`$\sin^{-1}$, $\tan^{-1}$, $\operatorname{cosec}^{-1}$ are odd; $\cos^{-1}(-x) = \pi - \cos^{-1} x$, and likewise for $\cot^{-1}$ and $\sec^{-1}$.`, v: negTable, n: 'For the sine family and the tangent, a negative input simply gives a negative output. For the cosine family the answer must stay between zero and pi, so a negative input gives pi minus the value at the positive input. The table checks each rule at zero point six.' }),
    sl('concept', 'Complementary sums', { b: r`$\sin^{-1} x + \cos^{-1} x = \dfrac{\pi}{2}$, $\tan^{-1} x + \cot^{-1} x = \dfrac{\pi}{2}$, $\sec^{-1} x + \operatorname{cosec}^{-1} x = \dfrac{\pi}{2}$.`, v: compTable, n: 'Three pairs always add up to a right angle. If you know the inverse sine of a number, you know its inverse cosine too. These identities let you replace one inverse function by another, which is often the first step in solving an equation.' }),
    sl('check', 'Quick check: true or false?', { b: 'Is the inverse cosine an odd function?', chk: 'tf2', n: 'Test it with minus one. The inverse cosine of minus one is pi.' }),
    sl('concept', 'One angle, many names', { b: r`For $0 < x \le 1$: $\cos^{-1} x = \sin^{-1}\sqrt{1 - x^2} = \tan^{-1}\dfrac{\sqrt{1 - x^2}}{x} = \sec^{-1}\dfrac1x$.`, v: convTable, n: 'Draw a right triangle with adjacent side x and hypotenuse one. The opposite side is the root of one minus x squared. Now the same acute angle can be named with any inverse function. At zero point six, all four names give the same angle, about zero point nine three radians.' }),
    sl('concept', 'Adding two inverse tangents', { b: r`$\tan^{-1} x + \tan^{-1} y = \tan^{-1}\dfrac{x + y}{1 - xy}$ when $xy < 1$; add or subtract $\pi$ when $xy > 1$.`, v: addTable, n: 'This is the most used formula of the chapter. When the product of the two numbers is less than one, the sum is the inverse tangent of x plus y over one minus x y. When the product is more than one, the sum leaves the principal range and we must add pi for positive numbers or subtract pi for negative ones.' }),
    sl('example', 'Worked example 4: a sum that is pi by four', { b: r`Show that $\tan^{-1}\dfrac34 + \tan^{-1}\dfrac17 = \dfrac{\pi}{4}$.`, ul: [r`$xy = \frac{3}{28} < 1$: the formula applies`, r`$\dfrac{\frac34 + \frac17}{1 - \frac{3}{28}} = \dfrac{\frac{25}{28}}{\frac{25}{28}} = 1$`, r`Sum $= \tan^{-1} 1 = \frac{\pi}{4}$`], v: we4Table, n: 'First check the product: three quarters times one seventh is three over twenty eight, less than one. Then the formula applies. The numerator and denominator both work out to twenty five over twenty eight, so the fraction is one, and the inverse tangent of one is pi by four.' }),
    sl('example', 'Worked example 5: a difference', { b: r`Simplify $\tan^{-1}\dfrac12 - \tan^{-1}\dfrac13$.`, ul: [r`$xy = \frac16 > -1$`, r`$\dfrac{\frac12 - \frac13}{1 + \frac16} = \dfrac{\frac16}{\frac76} = \dfrac17$`, r`Answer $\tan^{-1}\frac17$`], v: we5Table, n: 'For a difference, the denominator becomes one plus x y, and the condition is that x y is greater than minus one. Here x y is one sixth. The fraction simplifies to one seventh, so the difference is the inverse tangent of one seventh.' }),
    sl('check', 'Quick check: two angles of a set square', { b: 'Two inverse sines from a three, four, five triangle: what is their sum?', chk: 'm23', n: 'Draw the triangle. Is one angle the complement of the other?' }),
    sl('concept', 'Sums for inverse sine and cosine', { b: 'Name the angles $A$, $B$; expand $\\sin(A \\pm B)$ or $\\cos(A + B)$; check the range.', v: sinCosSum, n: 'For inverse sines and cosines the formulas look heavy, but the method is simple. Call the two angles A and B, find their sines and cosines from right triangles, expand the sine or cosine of the sum, and finally check that the sum lies in the principal range of the function you want.' }),
    sl('concept', 'Double forms of the inverse tangent', { b: r`$2\tan^{-1} x = \tan^{-1}\dfrac{2x}{1 - x^2} = \sin^{-1}\dfrac{2x}{1 + x^2} = \cos^{-1}\dfrac{1 - x^2}{1 + x^2}$, each with its condition.`, v: dblTable, n: 'Twice an inverse tangent can be written three ways, using the double-angle formulas for tangent, sine and cosine. Each version needs its own condition, so that twice the angle stays inside the principal range of the outer function. Always write the condition next to the formula.' }),
    sl('diagram', 'Where the double form is valid', { b: r`For $|x| < 1$ the curves $y = 2\tan^{-1} x$ and $y = \tan^{-1}\dfrac{2x}{1 - x^2}$ coincide.`, v: pDouble, n: 'The graph shows twice the inverse tangent of x together with the inverse tangent of two x over one minus x squared. Between minus one and one they are the same curve. Outside that interval, twice the angle is beyond pi by two in size, and the two expressions differ by pi.' }),
    sl('check', 'Quick check: a ramp angle', { b: 'Find the cosine of twice an inverse tangent.', chk: 'n03', n: 'Use the formula for cosine of a double angle in terms of the tangent.' }),
    sl('example', 'Worked example 6: an equation with an extra root', { b: r`Solve $2\tan^{-1} x = \sin^{-1}\dfrac45$.`, ul: [r`Take sines: $\dfrac{2x}{1 + x^2} = \dfrac45 \Rightarrow 2x^2 - 5x + 2 = 0$`, r`Roots $x = \frac12$ and $x = 2$`, r`At $x = 2$, $2\tan^{-1} 2 > \frac{\pi}{2}$, which no inverse sine can equal: reject. Answer $x = \frac12$`], v: we6Table, n: 'Taking the sine of both sides gives a quadratic with roots one half and two. Now test them. At two, twice the inverse tangent is more than pi by two, but an inverse sine is never more than pi by two, so two is rejected. Only one half satisfies the original equation.' }),
    sl('concept', 'Triple forms', { b: r`$3\tan^{-1} x = \tan^{-1}\dfrac{3x - x^3}{1 - 3x^2}$ for $|x| < \dfrac{1}{\sqrt3}$.`, v: triTable, n: 'The triple forms come from the formulas for tangent, sine and cosine of three theta. The conditions are tighter than for the double forms, because three times the angle must stay inside the principal range. For the inverse tangent the input must be smaller than one over root three in size.' }),
    sl('check', 'Quick check: the condition for the formula', { b: 'When is the inverse tangent addition formula guaranteed to hold?', chk: 'm22', n: 'Think about when the sum of the two angles stays between minus pi by two and pi by two.' }),
    sl('concept', 'Solving equations: a plan', { b: 'Combine, take a trigonometric function, solve, substitute back, reject.', v: eqFlow, n: 'Here is a plan for every equation. Combine the inverse terms into one using a formula. Take the tangent, sine or cosine of both sides. Solve the algebra. Then substitute each root into the original equation. A root that breaks a condition, or makes the two sides different, must be rejected.' }),
    sl('summary', 'Summary', { ul: ['Negative inputs: odd, or pi minus', 'Complementary pairs add to $\\frac{\\pi}{2}$', 'Sum formulae: check $xy < 1$ or the range', 'Double and triple forms need their conditions', 'Equations: test every root'], v: summary2, n: 'To sum up. Negative inputs make the sine family odd and give pi minus for the cosine family. Complementary pairs add to a right angle. The sum formulae work only under their conditions, as do the double and triple forms. And when you solve an equation, every root must be tested in the original.' }),
    sl('exam-tips', 'Exam tips', { ul: ['Write the condition beside every formula', 'Name the angles before expanding', 'Never stop at the roots of the quadratic', 'Give exact answers in terms of $\\pi$'], v: tips2, n: 'Some final advice for the examination. Write the condition next to every formula you use. Name the angles before expanding a sine or cosine. Never stop at the roots of a quadratic: substitute them back and reject the ones that fail. And give answers exactly, in terms of pi, unless a decimal is asked for.' }),
  ],
});

// ================================================================ notes
const notes = {
  unit: 'isc-12-mathematics-ch02', version: 1, title: 'Inverse Trigonometric Functions — chapter notes', language: 'en',
  sections: [
    { heading: '1. Principal-value branches', body_md: r`A trigonometric function is many-one, so it is first restricted to a **principal-value branch** on which it is one-one; the inverse returns angles only from that branch.\n\n- $\sin^{-1}$: domain $[-1, 1]$, range $\left[-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right]$; $\cos^{-1}$: domain $[-1, 1]$, range $[0, \pi]$.\n- $\tan^{-1}$: domain $\mathbb{R}$, range $\left(-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right)$; $\cot^{-1}$: domain $\mathbb{R}$, range $(0, \pi)$.\n- $\sec^{-1}$: domain $\mathbb{R} - (-1, 1)$, range $[0, \pi] - \left\{\dfrac{\pi}{2}\right\}$; $\operatorname{cosec}^{-1}$: same domain, range $\left[-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right] - \{0\}$.\n\n$\sin^{-1} x$ is **not** $\dfrac{1}{\sin x}$.`, key_terms: [{ term: 'Principal value', definition_md: 'The one value of an inverse trigonometric function that lies in its principal range.' }, { term: 'Principal-value branch', definition_md: 'The restricted interval on which a trigonometric function is one-one and is inverted.' }], formulas: [{ latex: r`\sin^{-1} x = \theta \iff \sin\theta = x,\ \theta \in \left[-\tfrac{\pi}{2}, \tfrac{\pi}{2}\right]`, label: 'Definition of the inverse sine' }], visual: branchTable, visuals: [we1Table], topic_ids: [topic(1)] },
    { heading: '2. Graphs', body_md: r`Each graph is the reflection of its branch in $y = x$.\n\n- $\sin^{-1} x$ rises from $\left(-1, -\dfrac{\pi}{2}\right)$ through $(0, 0)$ to $\left(1, \dfrac{\pi}{2}\right)$ (odd).\n- $\cos^{-1} x$ falls from $(-1, \pi)$ through $\left(0, \dfrac{\pi}{2}\right)$ to $(1, 0)$.\n- $\tan^{-1} x$ rises between the asymptotes $y = \pm\dfrac{\pi}{2}$; $\cot^{-1} x$ falls between $y = \pi$ and $y = 0$.\n- $\sec^{-1} x$ has two rising pieces and never reaches $\dfrac{\pi}{2}$.\n\nTransformations scale and shift the range: $y = 3\cos^{-1} x - \pi$ lies in $[-\pi, 2\pi]$.`, key_terms: [{ term: 'Horizontal asymptote', definition_md: r`A line such as $y = \frac{\pi}{2}$ that the graph of $\tan^{-1} x$ approaches but never meets.` }], formulas: [{ latex: r`\sin^{-1}(\sin\theta) = \theta \text{ only for } \theta \in \left[-\tfrac{\pi}{2}, \tfrac{\pi}{2}\right]`, label: 'Inverse of a trigonometric value' }], visual: pAsin, visuals: [pAcos, pAtanCot, invOfSin], topic_ids: [topic(2), topic(1)] },
    { heading: '3. Elementary properties', body_md: r`- **Negative arguments:** $\sin^{-1}(-x) = -\sin^{-1} x$, $\tan^{-1}(-x) = -\tan^{-1} x$, $\operatorname{cosec}^{-1}(-x) = -\operatorname{cosec}^{-1} x$; $\cos^{-1}(-x) = \pi - \cos^{-1} x$, $\cot^{-1}(-x) = \pi - \cot^{-1} x$, $\sec^{-1}(-x) = \pi - \sec^{-1} x$.\n- **Reciprocal relations:** $\sin^{-1}\dfrac1x = \operatorname{cosec}^{-1} x$ and $\cos^{-1}\dfrac1x = \sec^{-1} x$ for $|x| \ge 1$; $\tan^{-1}\dfrac1x = \cot^{-1} x$ for $x > 0$ and $\cot^{-1} x - \pi$ for $x < 0$.\n- **Complementary sums:** $\sin^{-1} x + \cos^{-1} x = \tan^{-1} x + \cot^{-1} x = \sec^{-1} x + \operatorname{cosec}^{-1} x = \dfrac{\pi}{2}$.\n- **Interconversion:** draw the right triangle; for example $\sin^{-1} x = \tan^{-1}\dfrac{x}{\sqrt{1 - x^2}}$ for $|x| < 1$.`, key_terms: [{ term: 'Interconversion', definition_md: 'Writing the same angle with a different inverse trigonometric function, using a right triangle.' }], formulas: [{ latex: r`\cos^{-1}(-x) = \pi - \cos^{-1} x`, label: 'Negative argument for the inverse cosine' }, { latex: r`\sin^{-1} x + \cos^{-1} x = \tfrac{\pi}{2}`, label: 'Complementary identity' }], visual: negTable, visuals: [compTable, convTable], topic_ids: [topic(3)] },
    { heading: '4. Sum and difference formulae', body_md: r`- $\tan^{-1} x + \tan^{-1} y = \tan^{-1}\dfrac{x + y}{1 - xy}$ if $xy < 1$; $= \pi + \tan^{-1}\dfrac{x + y}{1 - xy}$ if $xy > 1$, $x, y > 0$; $= -\pi + \tan^{-1}\dfrac{x + y}{1 - xy}$ if $xy > 1$, $x, y < 0$.\n- $\tan^{-1} x - \tan^{-1} y = \tan^{-1}\dfrac{x - y}{1 + xy}$ if $xy > -1$.\n- For $\sin^{-1}$ and $\cos^{-1}$: name the angles $A$ and $B$, expand $\sin(A \pm B)$ or $\cos(A \pm B)$ from right triangles, and check that the result lies in the principal range.`, key_terms: [{ term: 'Condition of a formula', definition_md: 'The restriction (such as xy < 1) that keeps the combined angle inside the principal range.' }], formulas: [{ latex: r`\tan^{-1} x + \tan^{-1} y = \tan^{-1}\frac{x + y}{1 - xy},\ xy < 1`, label: 'Inverse tangent addition' }, { latex: r`\tan^{-1} x - \tan^{-1} y = \tan^{-1}\frac{x - y}{1 + xy},\ xy > -1`, label: 'Inverse tangent subtraction' }], visual: addTable, visuals: [sinCosSum, we4Table], topic_ids: [topic(4)] },
    { heading: '5. Double and triple forms', body_md: r`- $2\tan^{-1} x = \tan^{-1}\dfrac{2x}{1 - x^2}$ ($|x| < 1$) $= \sin^{-1}\dfrac{2x}{1 + x^2}$ ($|x| \le 1$) $= \cos^{-1}\dfrac{1 - x^2}{1 + x^2}$ ($x \ge 0$).\n- $2\sin^{-1} x = \sin^{-1}\left(2x\sqrt{1 - x^2}\right)$ for $|x| \le \dfrac{1}{\sqrt2}$; $2\cos^{-1} x = \cos^{-1}(2x^2 - 1)$ for $0 \le x \le 1$.\n- $3\tan^{-1} x = \tan^{-1}\dfrac{3x - x^3}{1 - 3x^2}$ ($|x| < \dfrac{1}{\sqrt3}$); $3\sin^{-1} x = \sin^{-1}(3x - 4x^3)$ ($|x| \le \dfrac12$); $3\cos^{-1} x = \cos^{-1}(4x^3 - 3x)$ ($\dfrac12 \le x \le 1$).`, key_terms: [{ term: 'Double form', definition_md: r`An expression for $2\tan^{-1} x$ (or $2\sin^{-1} x$, $2\cos^{-1} x$) as a single inverse function.` }], formulas: [{ latex: r`2\tan^{-1} x = \tan^{-1}\frac{2x}{1 - x^2},\ |x| < 1`, label: 'Double form of the inverse tangent' }, { latex: r`3\tan^{-1} x = \tan^{-1}\frac{3x - x^3}{1 - 3x^2},\ |x| < \tfrac{1}{\sqrt3}`, label: 'Triple form of the inverse tangent' }], visual: dblTable, visuals: [pDouble, triTable], topic_ids: [topic(5)] },
    { heading: '6. Solving equations', body_md: r`1. Combine the inverse terms with a sum, double or complementary formula.\n2. Take $\tan$, $\sin$ or $\cos$ of both sides.\n3. Solve the algebraic equation.\n4. Substitute **every** root into the original equation; reject roots that break a condition or give a value outside a principal range.\n\nExample: $2\tan^{-1} x = \sin^{-1}\dfrac45$ gives $2x^2 - 5x + 2 = 0$, roots $\dfrac12$ and $2$; only $\dfrac12$ survives.`, key_terms: [{ term: 'Extraneous root', definition_md: 'A root of the algebraic equation that does not satisfy the original inverse-trigonometric equation.' }], formulas: [{ latex: r`\sin^{-1} x + \cos^{-1} x = \tfrac{\pi}{2} \Rightarrow \sin^{-1} x = \tfrac{\pi}{2} - \cos^{-1} x`, label: 'Replacing one inverse function by another' }], visual: eqFlow, visuals: [we6Table], topic_ids: [topic(5), topic(3)] },
  ],
  exam_tips_md: r`**How ISC marks are awarded**\n- *Principal value (1 mark):* only a value in the correct branch earns the mark.\n- *Identity proofs (3 marks):* angles named, formula with its condition, simplification.\n- *Equations (3–5 marks):* combining, algebra, testing each root and rejecting with a reason.\n- *Section D (5 marks):* questions come in parts such as 2 + 3; label each part.\n\n**Common mistakes**\n- Reading $\sin^{-1} x$ as $\dfrac{1}{\sin x}$.\n- Cancelling $\sin^{-1}(\sin\theta)$ to $\theta$ when $\theta$ is outside the branch.\n- Using the inverse tangent addition formula when $xy > 1$.\n- Giving a negative value for $\cos^{-1}$, $\cot^{-1}$ or $\sec^{-1}$.\n- Keeping both roots of the quadratic without checking them.`,
  status: 'draft', provenance: d1.provenance,
};

